T = int(input())
lens = []
max_l = 0
for _ in range(T):
    L = int(input())
    input()  # token，计数与内容无关
    lens.append(L)
    max_l = max(max_l, L)

fact = [1] * (max_l + 1)
for i in range(1, max_l + 1):
    fact[i] = fact[i - 1] * i % MOD

for L in lens:
    print(fact[L])
```

