import sys

MOD = 10**9 + 7

def main():
    data = sys.stdin.read().split()
    t = int(data[0])
    idx = 1
    ns = []
    max_n = 0
    for _ in range(t):
        n = int(data[idx]); idx += 1
        s = data[idx]; idx += 1  # 读入字符串 S，虽然用不到但需要消耗输入
        ns.append(n)
        if n > max_n:
            max_n = n

    # 预处理阶乘
    fact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i - 1] * i % MOD

    out = '\n'.join(str(fact[n]) for n in ns)
    sys.stdout.write(out)

if __name__ == "__main__":
    main()
```

